SET local check_function_bodies = off;

CREATE SCHEMA "api";

CREATE SCHEMA "better_supabase";

CREATE SCHEMA "rbac";

CREATE SCHEMA "workflow";

CREATE SEQUENCE "workflow"."workflow_invocations_sequence_seq" AS bigint INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1 NO CYCLE;

CREATE TABLE "better_supabase"."activity_entries" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "event_id"        text                     NOT NULL,
  "type"            text                     NOT NULL,
  "actor_id"        uuid,
  "subject_type"    text,
  "subject_id"      text,
  "summary"         text,
  "data"            jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "occurred_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "activity_entries_event_id_key" UNIQUE (event_id),
  CONSTRAINT "activity_entries_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."activity_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."agent_installs" (
  "agent_id"        uuid                     NOT NULL,
  "user_id"         uuid                     NOT NULL,
  "organization_id" uuid                     NOT NULL,
  "installed_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agent_installs_pkey" PRIMARY KEY (agent_id, user_id, organization_id)
);

ALTER TABLE "better_supabase"."agent_installs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."agent_ratings" (
  "agent_id"   uuid                     NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "rating"     smallint                 NOT NULL,
  "comment"    text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agent_ratings_comment_check" CHECK ((length(comment) <= 2000)),
  CONSTRAINT "agent_ratings_pkey" PRIMARY KEY (agent_id, user_id),
  CONSTRAINT "agent_ratings_rating_check" CHECK (((rating >= 1) AND (rating <= 5)))
);

ALTER TABLE "better_supabase"."agent_ratings"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."agent_skills" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "agent_id"   uuid                     NOT NULL,
  "provider"   text                     NOT NULL,
  "reference"  jsonb                    NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agent_skills_pkey" PRIMARY KEY (id),
  CONSTRAINT "agent_skills_provider_check" CHECK (((length(provider) >= 1) AND (length(provider) <= 100))),
  CONSTRAINT "agent_skills_reference_check" CHECK ((jsonb_typeof(reference) = 'object'::text))
);

ALTER TABLE "better_supabase"."agent_skills"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."agents" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "owner_id"        uuid,
  "slug"            text                     NOT NULL,
  "name"            text                     NOT NULL,
  "description"     text                     NOT NULL DEFAULT ''::text,
  "instructions"    text                     NOT NULL DEFAULT ''::text,
  "model"           text,
  "tools"           jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "connector_ids"   uuid[]                   NOT NULL DEFAULT '{}'::uuid[],
  "knowledge_scope" jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "starters"        jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "visibility"      text                     NOT NULL DEFAULT 'private'::text,
  "published_at"    timestamp with time zone,
  "install_count"   integer                  NOT NULL DEFAULT 0,
  "rating_count"    integer                  NOT NULL DEFAULT 0,
  "rating_sum"      integer                  NOT NULL DEFAULT 0,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agents_description_check" CHECK ((length(description) <= 2000)),
  CONSTRAINT "agents_instructions_check" CHECK ((length(instructions) <= 100000)),
  CONSTRAINT "agents_knowledge_scope_check" CHECK ((jsonb_typeof(knowledge_scope) = 'array'::text)),
  CONSTRAINT "agents_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "agents_organization_id_slug_key" UNIQUE (organization_id, slug),
  CONSTRAINT "agents_pkey" PRIMARY KEY (id),
  CONSTRAINT "agents_slug_check" CHECK (((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (length(slug) <= 64))),
  CONSTRAINT "agents_starters_check" CHECK ((jsonb_typeof(starters) = 'array'::text)),
  CONSTRAINT "agents_tools_check" CHECK ((jsonb_typeof(tools) = 'array'::text)),
  CONSTRAINT "agents_visibility_check" CHECK ((visibility = ANY (ARRAY['private'::text, 'organization'::text, 'public'::text])))
);

ALTER TABLE "better_supabase"."agents"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_batch_items" (
  "batch_id"        uuid                     NOT NULL,
  "request_id"      text                     NOT NULL,
  "organization_id" uuid                     NOT NULL,
  "status"          text                     NOT NULL,
  "output"          jsonb,
  "usage"           jsonb,
  "error"           text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_batch_items_error_check" CHECK ((length(error) <= 4000)),
  CONSTRAINT "ai_batch_items_pkey" PRIMARY KEY (batch_id, request_id),
  CONSTRAINT "ai_batch_items_request_id_check" CHECK (((length(request_id) >= 1) AND (length(request_id) <= 200))),
  CONSTRAINT "ai_batch_items_status_check" CHECK ((status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'cancelled'::text, 'expired'::text])))
);

ALTER TABLE "better_supabase"."ai_batch_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_batches" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "user_id"         uuid,
  "provider"        text                     NOT NULL,
  "reference"       jsonb                    NOT NULL,
  "status"          text                     NOT NULL DEFAULT 'pending'::text,
  "raw_status"      text,
  "item_count"      integer                  NOT NULL DEFAULT 0,
  "counts"          jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "error"           text,
  "metadata"        jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "results_saved"   boolean                  NOT NULL DEFAULT false,
  "polls"           integer                  NOT NULL DEFAULT 0,
  "next_poll_at"    timestamp with time zone DEFAULT now(),
  "expires_at"      timestamp with time zone,
  "completed_at"    timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_batches_counts_check" CHECK ((jsonb_typeof(counts) = 'object'::text)),
  CONSTRAINT "ai_batches_error_check" CHECK ((length(error) <= 4000)),
  CONSTRAINT "ai_batches_item_count_check" CHECK ((item_count >= 0)),
  CONSTRAINT "ai_batches_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "ai_batches_pkey" PRIMARY KEY (id),
  CONSTRAINT "ai_batches_provider_check" CHECK (((length(provider) >= 1) AND (length(provider) <= 100))),
  CONSTRAINT "ai_batches_raw_status_check" CHECK ((length(raw_status) <= 100)),
  CONSTRAINT "ai_batches_reference_check" CHECK ((jsonb_typeof(reference) = 'object'::text)),
  CONSTRAINT "ai_batches_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])))
);

ALTER TABLE "better_supabase"."ai_batches"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_cache_entries" (
  "key"             text                     NOT NULL,
  "organization_id" uuid,
  "kind"            text                     NOT NULL DEFAULT 'generate'::text,
  "model"           text,
  "value"           jsonb                    NOT NULL,
  "hits"            integer                  NOT NULL DEFAULT 0,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "last_hit_at"     timestamp with time zone,
  "expires_at"      timestamp with time zone NOT NULL,
  CONSTRAINT "ai_cache_entries_key_check" CHECK (((length(key) >= 1) AND (length(key) <= 256))),
  CONSTRAINT "ai_cache_entries_kind_check" CHECK ((kind = ANY (ARRAY['generate'::text, 'stream'::text, 'embed'::text, 'other'::text]))),
  CONSTRAINT "ai_cache_entries_model_check" CHECK ((length(model) <= 200)),
  CONSTRAINT "ai_cache_entries_pkey" PRIMARY KEY (key),
  CONSTRAINT "ai_cache_entries_value_check" CHECK ((octet_length((value)::text) <= 1048576))
);

ALTER TABLE "better_supabase"."ai_cache_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_chat_shares" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "chat_id"    uuid                     NOT NULL,
  "token_hash" text                     NOT NULL,
  "leaf_id"    text                     NOT NULL,
  "created_by" uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "revoked_at" timestamp with time zone,
  CONSTRAINT "ai_chat_shares_pkey" PRIMARY KEY (id),
  CONSTRAINT "ai_chat_shares_token_hash_check" CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text)),
  CONSTRAINT "ai_chat_shares_token_hash_key" UNIQUE (token_hash)
);

ALTER TABLE "better_supabase"."ai_chat_shares"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_chats" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id"  uuid                     NOT NULL,
  "owner_id"         uuid                     NOT NULL,
  "project_id"       uuid,
  "agent_id"         text,
  "title"            text                     NOT NULL DEFAULT ''::text,
  "model"            text,
  "visibility"       text                     NOT NULL DEFAULT 'private'::text,
  "pinned"           boolean                  NOT NULL DEFAULT false,
  "archived_at"      timestamp with time zone,
  "is_temporary"     boolean                  NOT NULL DEFAULT false,
  "expires_at"       timestamp with time zone,
  "current_leaf_id"  text,
  "active_stream_id" text,
  "active_run_id"    uuid,
  "last_message_at"  timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_chats_agent_id_check" CHECK ((length(agent_id) <= 200)),
  CONSTRAINT "ai_chats_check" CHECK (((NOT is_temporary) OR (expires_at IS NOT NULL))),
  CONSTRAINT "ai_chats_model_check" CHECK ((length(model) <= 200)),
  CONSTRAINT "ai_chats_pkey" PRIMARY KEY (id),
  CONSTRAINT "ai_chats_title_check" CHECK ((length(title) <= 300)),
  CONSTRAINT "ai_chats_visibility_check" CHECK ((visibility = ANY (ARRAY['private'::text, 'organization'::text])))
);

ALTER TABLE "better_supabase"."ai_chats"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_document_versions" (
  "document_id"           uuid                     NOT NULL,
  "version"               integer                  NOT NULL,
  "content"               text,
  "storage_path"          text,
  "created_by_message_id" text,
  "created_by"            uuid,
  "created_at"            timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_document_versions_check" CHECK (((content IS NOT NULL) OR (storage_path IS NOT NULL))),
  CONSTRAINT "ai_document_versions_pkey" PRIMARY KEY (document_id, VERSION),
  CONSTRAINT "ai_document_versions_version_check" CHECK ((version >= 1))
);

ALTER TABLE "better_supabase"."ai_document_versions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_documents" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "owner_id"        uuid                     NOT NULL,
  "chat_id"         uuid,
  "kind"            text                     NOT NULL,
  "title"           text                     NOT NULL,
  "current_version" integer                  NOT NULL DEFAULT 1,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_documents_current_version_check" CHECK ((current_version >= 1)),
  CONSTRAINT "ai_documents_kind_check" CHECK ((kind = ANY (ARRAY['text'::text, 'code'::text, 'sheet'::text, 'image'::text]))),
  CONSTRAINT "ai_documents_pkey" PRIMARY KEY (id),
  CONSTRAINT "ai_documents_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 500)))
);

ALTER TABLE "better_supabase"."ai_documents"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_files" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "owner_id"        uuid                     NOT NULL,
  "chat_id"         uuid,
  "project_id"      uuid,
  "bucket"          text                     NOT NULL,
  "filename"        text                     NOT NULL,
  "media_type"      text                     NOT NULL,
  "byte_size"       bigint                   NOT NULL,
  "sha256"          text,
  "status"          text                     NOT NULL DEFAULT 'pending'::text,
  "source"          text                     NOT NULL DEFAULT 'upload'::text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "uploaded_at"     timestamp with time zone,
  "expires_at"      timestamp with time zone,
  CONSTRAINT "ai_files_byte_size_check" CHECK (((byte_size >= 0) AND (byte_size <= 52428800))),
  CONSTRAINT "ai_files_filename_check"
    CHECK (((length(filename) >= 1) AND (length(filename) <= 255) AND (filename !~ '[/\\]'::text) AND (filename <> ALL (ARRAY['.'::text, '..'::text])))),
  CONSTRAINT "ai_files_media_type_check" CHECK ((media_type ~ '^[a-z0-9.+-]+/[a-z0-9.+-]+$'::text)),
  CONSTRAINT "ai_files_pkey" PRIMARY KEY (id),
  CONSTRAINT "ai_files_sha256_check" CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
  CONSTRAINT "ai_files_source_check" CHECK ((source = ANY (ARRAY['upload'::text, 'generated'::text, 'provider'::text]))),
  CONSTRAINT "ai_files_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text, 'failed'::text])))
);

ALTER TABLE "better_supabase"."ai_files"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_harness_sessions" (
  "chat_id"        uuid                     NOT NULL,
  "harness_id"     text                     NOT NULL,
  "owner_id"       uuid                     NOT NULL,
  "resume_state"   jsonb,
  "continue_state" jsonb,
  "status"         text                     NOT NULL DEFAULT 'active'::text,
  "lock_holder"    text,
  "locked_until"   timestamp with time zone,
  "last_active_at" timestamp with time zone NOT NULL DEFAULT now(),
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_harness_sessions_harness_id_check" CHECK (((length(harness_id) >= 1) AND (length(harness_id) <= 200))),
  CONSTRAINT "ai_harness_sessions_lock_holder_check" CHECK ((length(lock_holder) <= 200)),
  CONSTRAINT "ai_harness_sessions_pkey" PRIMARY KEY (chat_id, harness_id),
  CONSTRAINT "ai_harness_sessions_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'idle'::text, 'stopped'::text, 'error'::text])))
);

ALTER TABLE "better_supabase"."ai_harness_sessions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_message_embeddings" (
  "chat_id"         uuid                     NOT NULL,
  "message_id"      text                     NOT NULL,
  "user_id"         uuid                     NOT NULL,
  "organization_id" uuid                     NOT NULL,
  "embedding"       extensions.vector(1536)  NOT NULL,
  "embedding_model" text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_message_embeddings_pkey" PRIMARY KEY (chat_id, message_id)
);

ALTER TABLE "better_supabase"."ai_message_embeddings"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_message_feedback" (
  "chat_id"    uuid                     NOT NULL,
  "message_id" text                     NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "rating"     smallint                 NOT NULL,
  "reason"     text,
  "comment"    text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_message_feedback_comment_check" CHECK ((length(comment) <= 4000)),
  CONSTRAINT "ai_message_feedback_pkey" PRIMARY KEY (chat_id, message_id, user_id),
  CONSTRAINT "ai_message_feedback_rating_check" CHECK ((rating = ANY (ARRAY['-1'::integer, 1]))),
  CONSTRAINT "ai_message_feedback_reason_check" CHECK ((length(reason) <= 200))
);

ALTER TABLE "better_supabase"."ai_message_feedback"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_message_sources" (
  "chat_id"           uuid  NOT NULL,
  "message_id"        text  NOT NULL,
  "source_id"         text  NOT NULL,
  "source_type"       text  NOT NULL DEFAULT 'url'::text,
  "url"               text,
  "title"             text,
  "provider_metadata" jsonb,
  CONSTRAINT "ai_message_sources_pkey" PRIMARY KEY (chat_id, message_id, source_id),
  CONSTRAINT "ai_message_sources_source_type_check" CHECK ((source_type = ANY (ARRAY['url'::text, 'document'::text])))
);

ALTER TABLE "better_supabase"."ai_message_sources"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_messages" (
  "chat_id"    uuid                     NOT NULL,
  "id"         text                     NOT NULL,
  "parent_id"  text,
  "owner_id"   uuid                     NOT NULL,
  "role"       text                     NOT NULL,
  "parts"      jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "format"     text                     NOT NULL DEFAULT 'canonical'::text,
  "native"     jsonb,
  "metadata"   jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "model"      text,
  "status"     text                     NOT NULL DEFAULT 'complete'::text,
  "seq"        bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_messages_format_check" CHECK (((length(format) >= 1) AND (length(format) <= 50))),
  CONSTRAINT "ai_messages_id_check" CHECK (((length(id) >= 1) AND (length(id) <= 200))),
  CONSTRAINT "ai_messages_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "ai_messages_parts_check"
    CHECK
    (((jsonb_typeof(parts) = 'array'::text) AND (NOT jsonb_path_exists(parts,
    '$[*]?(!((((((((@."type" == "text" || @."type" == "reasoning") || @."type" == "file") || @."type" == "tool-call") || @."type" == "tool-result") || @."type" == "tool-approval") || @."type" == "source") || @."type" == "data") || @."type" == "step"))'::jsonpath)))),
  CONSTRAINT "ai_messages_pkey" PRIMARY KEY (chat_id, id),
  CONSTRAINT "ai_messages_role_check" CHECK ((role = ANY (ARRAY['system'::text, 'user'::text, 'assistant'::text, 'tool'::text]))),
  CONSTRAINT "ai_messages_status_check" CHECK ((status = ANY (ARRAY['complete'::text, 'aborted'::text, 'error'::text])))
);

ALTER TABLE "better_supabase"."ai_messages"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."ai_model_catalog" (
  "model_id"     text                     NOT NULL,
  "provider"     text                     NOT NULL DEFAULT ''::text,
  "name"         text                     NOT NULL DEFAULT ''::text,
  "pricing"      jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "capabilities" jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "plans"        text[]                   NOT NULL DEFAULT '{}'::text[],
  "enabled"      boolean                  NOT NULL DEFAULT true,
  "refreshed_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "ai_model_catalog_model_id_check" CHECK (((length(model_id) >= 1) AND (length(model_id) <= 200))),
  CONSTRAINT "ai_model_catalog_pkey" PRIMARY KEY (model_id)
);

ALTER TABLE "better_supabase"."ai_model_catalog"
  ENABLE ROW LEVEL SECURITY;

