  v_project := (memory_view.ns ->> 'project_id')::uuid;
  v_owner := case when v_scope = 'organization' then null when coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then (memory_view.ns ->> 'owner_id')::uuid else auth.uid() end;
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and (auth.uid() is null or not coalesce(better_supabase.can('tenant', memory_view.tenant, 'ai.read'), false)) then
    raise exception 'you may not use memory here' using errcode = '42501', hint = 'MEMORY_FORBIDDEN';
  end if;
  if v_scope not in ('user', 'agent', 'chat', 'project', 'organization')
    or (v_scope = 'agent') <> (v_agent is not null)
    or (v_scope = 'chat') <> (v_chat is not null)
    or (v_scope = 'project') <> (v_project is not null)
    or (v_scope <> 'organization' and v_owner is null) then
    raise exception 'ns % is not a memory namespace', memory_view.ns using errcode = '22023', hint = 'MEMORY_NAMESPACE';
  end if;
  if memory_view.path is null or length(memory_view.path) > 500 or memory_view.path !~ '^/memories(/[A-Za-z0-9._ -]+)*$' or memory_view.path ~ '(^|/)[.]{1,2}(/|$)' then
    raise exception '% is not a path under /memories', memory_view.path using errcode = '22023', hint = 'MEMORY_PATH';
  end if;
  select * into v_row from "better_supabase"."memories" x
  where x."organization_id" = memory_view.tenant and x."owner_id" is not distinct from v_owner and x."scope" = v_scope and x."agent_id" is not distinct from v_agent and x."chat_id" is not distinct from v_chat and x."project_id" is not distinct from v_project and x."superseded_by" is null and x."path" = memory_view.path;
  if found then
    return jsonb_build_object('type', 'file', 'path', v_row."path", 'content', v_row."content", 'version', v_row."version", 'updated_at', v_row."updated_at");
  end if;
  select jsonb_agg(jsonb_build_object('path', x."path", 'size', length(x."content"), 'updated_at', x."updated_at") order by x."path")
  into v_entries
  from "better_supabase"."memories" x
  where x."organization_id" = memory_view.tenant and x."owner_id" is not distinct from v_owner and x."scope" = v_scope and x."agent_id" is not distinct from v_agent and x."chat_id" is not distinct from v_chat and x."project_id" is not distinct from v_project and x."superseded_by" is null and x."path" like replace(replace(memory_view.path, '_', '\_'), '%', '\%') || '/%';
  if v_entries is null and memory_view.path <> '/memories' then
    return null;
  end if;
  return jsonb_build_object('type', 'directory', 'path', memory_view.path, 'entries', coalesce(v_entries, '[]'));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.metric_definitions()
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$ select '[{"key":"customers","label":"Customers","unit":null,"measure":"count","dimensions":["status"],"grains":[],"tz":"UTC"}]'::jsonb $function$;

CREATE OR REPLACE FUNCTION better_supabase.metric_series (
  p_metric   text,
  p_tenant   uuid,
  p_from     timestamp with time zone,
  p_until    timestamp with time zone,
  p_grain    text                     DEFAULT 'day'::text,
  p_dims     jsonb                    DEFAULT '{}'::jsonb,
  p_group_by text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_source text;
  v_start timestamptz;
  v_buckets integer;
begin
  if p_grain is null or p_grain <> all (array['hour', 'day', 'week', 'month']::text[]) then
    raise exception 'grain must be hour, day, week or month' using errcode = '22023', hint = 'METRIC_GRAIN_INVALID';
  end if;
  if p_from is null or p_until is null or p_until <= p_from then
    raise exception 'the range needs a start before its end' using errcode = '22023', hint = 'METRIC_RANGE_INVALID';
  end if;
  case p_metric
    when 'customers' then
      if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', p_tenant, 'metrics.read'), false)) then
        raise exception 'you cannot read this metric in this organization' using errcode = '42501', hint = 'METRIC_FORBIDDEN';
      end if;
      if exists (
        select 1 from jsonb_object_keys(coalesce(p_dims, '{}'::jsonb)) k
        where k <> all (array['status']::text[])
      ) then
        raise exception 'a filter names a column that is not a dimension of this metric' using errcode = '22023', hint = 'METRIC_DIMENSION_UNKNOWN';
      end if;
      if p_group_by is not null and p_group_by <> all (array['status']::text[]) then
        raise exception 'group_by is not a dimension of this metric' using errcode = '22023', hint = 'METRIC_DIMENSION_UNKNOWN';
      end if;
      v_source := null;
      v_start := date_trunc(p_grain, p_from, 'UTC');
      select count(*) into v_buckets
        from generate_series(v_start at time zone 'UTC', (p_until at time zone 'UTC') - interval '1 microsecond', ('1 ' || p_grain)::interval);
      if v_buckets > 1000 then
        raise exception 'a series returns at most 1000 buckets; pick a coarser grain' using errcode = '22023', hint = 'METRIC_RANGE_TOO_LARGE';
      end if;
      return (
        with source as (
      select s.at, s.dims, s.value, s.count
        from (select t."organization_id" as tenant, t."created_at" as at, jsonb_build_object('status', t."status") as dims, 1::numeric as value, 1::bigint as count
        from "public"."customers" t
        where t."archived_at" is null) s
        where v_source is null
          and s.tenant = p_tenant
          and s.at >= v_start
          and s.at < p_until
          and s.dims @> coalesce(p_dims, '{}'::jsonb)
    ),
        buckets as (
          select b at time zone 'UTC' as bucket
            from generate_series(v_start at time zone 'UTC', (p_until at time zone 'UTC') - interval '1 microsecond', ('1 ' || p_grain)::interval) b
        ),
        grouped as (
          select date_trunc(p_grain, s.at, 'UTC') as bucket,
                 case when p_group_by is null then null else s.dims ->> p_group_by end as grp,
                 sum(s.value) as value,
                 sum(s.count) as count
            from source s
            group by 1, 2
        ),
        per_bucket as (
          select g.bucket, sum(g.value) as value, sum(g.count) as count,
                 jsonb_object_agg(coalesce(g.grp, ''), coalesce(g.value, 0)) as groups
            from grouped g
            group by g.bucket
        )
        select coalesce(jsonb_agg(
          jsonb_build_object('bucket', b.bucket, 'value', coalesce(p.value, 0), 'count', coalesce(p.count, 0))
            || case when p_group_by is null then '{}'::jsonb else jsonb_build_object('groups', coalesce(p.groups, '{}'::jsonb)) end
          order by b.bucket), '[]'::jsonb)
          from buckets b
          left join per_bucket p on p.bucket = b.bucket
      );
    else
      raise exception 'no metric has this key' using errcode = '22023', hint = 'METRIC_UNKNOWN';
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.metric_value (
  p_metric text,
  p_tenant uuid,
  p_from   timestamp with time zone,
  p_until  timestamp with time zone,
  p_dims   jsonb                    DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_source text;
begin
  if p_from is null or p_until is null or p_until <= p_from then
    raise exception 'the range needs a start before its end' using errcode = '22023', hint = 'METRIC_RANGE_INVALID';
  end if;
  case p_metric
    when 'customers' then
      if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', p_tenant, 'metrics.read'), false)) then
        raise exception 'you cannot read this metric in this organization' using errcode = '42501', hint = 'METRIC_FORBIDDEN';
      end if;
      if exists (
        select 1 from jsonb_object_keys(coalesce(p_dims, '{}'::jsonb)) k
        where k <> all (array['status']::text[])
      ) then
        raise exception 'a filter names a column that is not a dimension of this metric' using errcode = '22023', hint = 'METRIC_DIMENSION_UNKNOWN';
      end if;
      v_source := null;
      return (
        with source as (
      select s.at, s.dims, s.value, s.count
        from (select t."organization_id" as tenant, t."created_at" as at, jsonb_build_object('status', t."status") as dims, 1::numeric as value, 1::bigint as count
        from "public"."customers" t
        where t."archived_at" is null) s
        where v_source is null
          and s.tenant = p_tenant
          and s.at >= p_from
          and s.at < p_until
          and s.dims @> coalesce(p_dims, '{}'::jsonb)
    ),
        total as (select sum(s.value) as value, sum(s.count) as count from source s)
        select jsonb_build_object('value', coalesce(t.value, 0), 'count', coalesce(t.count, 0))
          from total t
      );
    else
      raise exception 'no metric has this key' using errcode = '22023', hint = 'METRIC_UNKNOWN';
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.metrics_rollup (
  p_metric text                     DEFAULT NULL::text,
  p_since  timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_until  timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_since timestamptz := coalesce(p_since, now() - interval '3 days');
  v_until timestamptz := coalesce(p_until, now());
  v_from timestamptz;
  v_to timestamptz;
  v_rows integer;
  v_total integer := 0;
begin
  if p_metric is not null and p_metric <> all (array['customers']::text[]) then
    raise exception 'no metric has this key' using errcode = '22023', hint = 'METRIC_UNKNOWN';
  end if;
  if v_until <= v_since then
    return 0;
  end if;
  perform pg_advisory_xact_lock(hashtext('better_supabase.metrics_rollup'));

  return v_total;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.mirror_profile_email()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update "better_supabase"."profiles" set "email" = new.email where "id" = new.id and "email" is distinct from new.email;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.my_invitations()
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  invitee_email text;
  result jsonb := '[]'::jsonb;
begin
  select lower(u.email) into invitee_email
  from auth.users u
  where u.id = auth.uid() and u.email_confirmed_at is not null;
  if invitee_email is null then
    return result;
  end if;
  select coalesce(jsonb_agg(x.invitation order by x.expires_at), '[]'::jsonb)
  into result
  from (
    select (jsonb_build_object(
    'id', i."id",
    'tenant', i."organization_id",
    'email', i."email",
    'role', i."role",
    'expires_at', i."expires_at",
    'created_at', i."created_at",
    'invited_by', i."invited_by",
    'organization', (select jsonb_build_object('id', o."id", 'name', o."name")
      from "public"."organizations" o where o."id" = i."organization_id"),
    'prefill', '{}'::jsonb,
    'inviter', (select jsonb_build_object('id', pr."id", 'username', pr."username", 'fullName', pr."full_name", 'firstName', pr."first_name", 'lastName', pr."last_name", 'avatar', pr."avatar_url")
      from "better_supabase"."profiles" pr where pr."id" = i."invited_by"),
    'token', null
  ) || "better_supabase"."invitation_extra"(i."id")) - 'token' as invitation, i."id" as id, i."expires_at" as expires_at
    from "better_supabase"."invitations" i
    where lower(i."email") = invitee_email
      and i."expires_at" >= now() and i."accepted_at" is null and i."declined_at" is null and i."revoked_at" is null
  ) x;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.my_profile()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select to_jsonb(p) from "better_supabase"."profiles" p where p."id" = (select auth.uid())
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_actors (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_object_agg(pr."id"::text, jsonb_build_object('id', pr."id", 'username', pr."username", 'fullName', pr."full_name", 'firstName', pr."first_name", 'lastName', pr."last_name", 'avatar', pr."avatar_url", 'avatarPath', pr."avatar_path")), '{}')
  from "better_supabase"."profiles" pr
  where pr."id" = any(notification_actors.ids)
    and exists (
      select 1 from "better_supabase"."notification_recipients" rc
      join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
      where rc."user_id" = auth.uid() and ev."actor_id" = pr."id"
    )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_counts (
  tenant     uuid   DEFAULT NULL::uuid,
  actionable text[] DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'unread', count(*) filter (where rc."read_at" is null),
    'actionable', count(*) filter (
      where rc."resolved_at" is null and ev."type" = any(coalesce(notification_counts.actionable, '{}'))
    ),
    'actionable_subjects', count(distinct case when ev."subject_type" is not null and ev."subject_id" is not null then jsonb_build_array(ev."organization_id", ev."subject_type", ev."subject_id")::text else rc."id"::text end) filter (
      where rc."resolved_at" is null and ev."type" = any(coalesce(notification_counts.actionable, '{}'))
    )
  )
  from "better_supabase"."notification_recipients" rc
  join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
  where rc."user_id" = auth.uid()
    and rc."dismissed_at" is null
    and (notification_counts.tenant is null or rc."organization_id" = notification_counts.tenant)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_enabled (
  member  uuid,
  tenant  uuid,
  type    text,
  channel text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce((
    select p."enabled"
    from "better_supabase"."notification_preferences" p
    where p."user_id" = notification_enabled.member
      and p."channel" = notification_enabled.channel
      and (p."type" = notification_enabled.type or p."type" = '*')
      and (p."organization_id" is null or p."organization_id" = notification_enabled.tenant)
    order by p."organization_id" is null, p."type" = '*'
    limit 1
  ), case notification_enabled.channel when 'in_app' then true else false end)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_page (
  tenant        uuid    DEFAULT NULL::uuid,
  status        text    DEFAULT 'all'::text,
  types         text[]  DEFAULT NULL::text[],
  subject_types text[]  DEFAULT NULL::text[],
  search        text    DEFAULT NULL::text,
  max_items     integer DEFAULT 50,
  skip          integer DEFAULT 0,
  read          boolean DEFAULT NULL::boolean,
  resolved      boolean DEFAULT NULL::boolean,
  dismissed     boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with matched as (
    select jsonb_build_object('id', rc."id", 'event_id', ev."id", 'type', ev."type", 'data', ev."data", 'created_at', rc."created_at", 'read_at', rc."read_at", 'tenant', ev."organization_id", 'actor_id', ev."actor_id", 'subject_type', ev."subject_type", 'subject_id', ev."subject_id", 'subject_label', ev."subject_label", 'summary', ev."summary", 'action_path', ev."action_path", 'priority', ev."priority", 'resolved_at', rc."resolved_at") as item, rc."created_at" as created_at, rc."id" as id
    from "better_supabase"."notification_recipients" rc
    join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
    where rc."user_id" = auth.uid()
      and case when coalesce(notification_page.status, 'all') = 'settled' then (rc."resolved_at" is not null or rc."dismissed_at" is not null) when notification_page.dismissed is null then true else (rc."dismissed_at" is not null) = notification_page.dismissed end
      and (notification_page.read is null or (rc."read_at" is not null) = notification_page.read)
      and (notification_page.resolved is null or (rc."resolved_at" is not null) = notification_page.resolved)
      and (notification_page.tenant is null or rc."organization_id" = notification_page.tenant)
      and (notification_page.types is null or ev."type" = any(notification_page.types))
      and (notification_page.subject_types is null or ev."subject_type" = any(notification_page.subject_types))
      and (notification_page.search is null or btrim(notification_page.search) = '' or concat_ws(' ', ev."summary", ev."subject_label", ev."type") ilike '%' || replace(replace(replace(btrim(notification_page.search), chr(92), chr(92) || chr(92)), '%', chr(92) || '%'), '_', chr(92) || '_') || '%')
      and case coalesce(notification_page.status, 'all')
        when 'unread' then rc."read_at" is null
        when 'read' then rc."read_at" is not null
        when 'unresolved' then rc."resolved_at" is null
        else true
      end
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(p.item order by p.created_at desc, p.id desc)
      from (
        select m.item, m.created_at, m.id from matched m
        order by m.created_at desc, m.id desc
        offset greatest(coalesce(notification_page.skip, 0), 0)
        limit least(greatest(coalesce(notification_page.max_items, 50), 1), 200)
      ) p
    ), '[]'),
    'total', (select count(*) from matched)
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notify (
  notification jsonb
)
  RETURNS uuid
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  select ("better_supabase"."send_notification"(notification) ->> 'id')::uuid
$function$;

CREATE OR REPLACE FUNCTION better_supabase.on_auth_user_created()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- A failure here would abort the sign-up. The user gets an account
  -- without a profile instead, and backfill_profiles() creates it later.
  begin
    perform "better_supabase"."sync_profile"(new.id);
  exception when others then
    raise warning 'No profile for user %: % (SQLSTATE %). Run backfill_profiles() once it is fixed.',
      new.id, sqlerrm, sqlstate;
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.onboarding_progress (
  checklist text,
  tenant    uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_scope text;
begin
  v_scope := (select s.scope from (values ('getting-started', 'customer', 'organization'), ('getting-started', 'invite', 'organization'), ('getting-started', 'api-key', 'organization'), ('getting-started', 'plan', 'organization')) as s(checklist, step, scope) where s.checklist = onboarding_progress.checklist and (null::text is null or s.step = null::text) limit 1);
  if v_scope is null then
    raise exception 'Unknown onboarding checklist %', onboarding_progress.checklist using errcode = '22023', hint = 'ONBOARDING_STEP_UNKNOWN';
  end if;
  if v_scope = 'organization' then
    if onboarding_progress.tenant is null then
      raise exception 'Checklist % belongs to an organization', onboarding_progress.checklist using errcode = '22023', hint = 'ONBOARDING_SCOPE';
    end if;
    if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', onboarding_progress.tenant, 'onboarding.read'), false)) then
      raise exception 'You may not see this organization''s onboarding' using errcode = '42501', hint = 'ONBOARDING_FORBIDDEN';
    end if;
  elsif onboarding_progress.tenant is not null then
    raise exception 'Checklist % belongs to a user', onboarding_progress.checklist using errcode = '22023', hint = 'ONBOARDING_SCOPE';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'step', x."step",
      'completedAt', x."completed_at",
      'completedBy', x."completed_by"
    ) order by x."completed_at"), '[]'::jsonb)
    from "better_supabase"."onboarding_progress" x
    where x."checklist" = onboarding_progress.checklist
      and (case when v_scope = 'organization' then x."organization_id" = onboarding_progress.tenant else x."user_id" = auth.uid() end)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.open_ai_pending_input (
  chat  uuid,
  input jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_chat "better_supabase"."ai_chats";
  v_row "better_supabase"."ai_pending_inputs";
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'Only the server records this' using errcode = '42501', hint = 'AI_CHAT_FORBIDDEN';
  end if;
  select * into v_chat from "better_supabase"."ai_chats" x where x."id" = open_ai_pending_input.chat;
  if not found then
    raise exception 'No chat %', open_ai_pending_input.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  insert into "better_supabase"."ai_pending_inputs" ("chat_id", "owner_id", "run_id", "tool_call_id", "question", "schema")
  values (
    v_chat."id", v_chat."owner_id", (open_ai_pending_input.input ->> 'run_id')::uuid,
    open_ai_pending_input.input ->> 'tool_call_id', open_ai_pending_input.input ->> 'question',
    open_ai_pending_input.input -> 'schema'
  )
  returning * into v_row;
  perform "better_supabase"."ai_chat_notify"(v_chat."id", null, 'input.requested', jsonb_build_object('inputId', v_row."id"), false);
  return jsonb_build_object('id', v_row."id", 'chat_id', v_row."chat_id", 'run_id', v_row."run_id", 'tool_call_id', v_row."tool_call_id", 'question', v_row."question", 'schema', v_row."schema", 'answer', v_row."answer", 'answered_at', v_row."answered_at", 'created_at', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.organization_member_role (
  organization uuid,
  member       uuid
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select m.role
  from public.memberships m
  where m.organization_id = organization and m.user_id = member
$function$;

CREATE OR REPLACE FUNCTION better_supabase.organization_slug_problem (
  value               text,
  except_organization uuid DEFAULT NULL::uuid
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select case
    when value is null then null
    when length(value) < 2 or length(value) > 48 or value !~ '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$' then 'invalid'
    when false then 'reserved'
    when exists (
      select 1 from "public"."organizations" o
      where lower(o."slug"::text) = lower(value)
        and o."id" is distinct from except_organization
    ) then 'taken'
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.pause_workflow_schedule (
  schedule uuid,
  paused   boolean DEFAULT true
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  update "better_supabase"."workflow_schedules" x set "paused" = coalesce(paused, true)
  where x."id" = schedule
    and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (x."tenant_id" is not null and coalesce(better_supabase.can('tenant', x."tenant_id", 'workflow.admin'), false)));
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.pending_inbound_events (
  max          integer DEFAULT 100,
  max_attempts integer DEFAULT 5
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(e) order by e."received_at"), '[]'::jsonb)
  from (
    select * from "better_supabase"."inbound_events" x
    where x."status" in ('received', 'failed') and x."attempts" < coalesce(max_attempts, 5)
    order by x."received_at"
    limit least(greatest(coalesce(max, 100), 1), 1000)
  ) e;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.pending_knowledge_chunks (
  document_id uuid,
  batch       integer DEFAULT 64
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('idx', x."idx", 'content', x."content", 'hash', md5(x."content")) order by x."idx"), '[]')
  from (
    select * from "better_supabase"."knowledge_chunks" y
    where y."document_id" = pending_knowledge_chunks.document_id and y."embedding" is null
    order by y."idx"
    limit least(greatest(pending_knowledge_chunks.batch, 1), 2048)
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.pending_knowledge_documents (
  batch integer DEFAULT 10
)
  RETURNS jsonb
