CREATE UNIQUE INDEX workflow_versions_one_published_idx ON better_supabase.workflow_versions USING btree (definition_id)
  WHERE (status = 'published'::text);

CREATE INDEX workflow_versions_published_by_idx ON better_supabase.workflow_versions USING btree (published_by);

CREATE INDEX contacts_organization_id_created_at_idx ON public.contacts USING btree (organization_id, created_at DESC);

