CREATE INDEX locations_organization_id_created_at_idx ON public.locations USING btree (organization_id, created_at DESC);

CREATE INDEX memberships_user_idx ON public.memberships USING btree (user_id);

CREATE INDEX notes_customer_id_idx ON public.notes USING btree (customer_id, organization_id, created_at DESC);

CREATE INDEX notes_embedding_idx ON public.notes USING hnsw (embedding extensions.vector_cosine_ops);

