CREATE POLICY "bs_inbox_broadcast" ON "realtime"."messages"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((extension = ANY (ARRAY['broadcast'::text, 'presence'::text])) AND (( SELECT realtime.topic() AS topic) ~~ ('inbox:'::text || '%'::text)) AND (( SELECT realtime.topic() AS
    topic) !~~ ('inbox:org:'::text || '%'::text)) AND better_supabase.inbox_conversation_allowed(substr(( SELECT realtime.topic() AS topic), 7)) AND
    ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

CREATE POLICY "bs_inbox_receive" ON "realtime"."messages"
  FOR SELECT
  TO "authenticated"
  USING
    (((EXTENSION = ANY (ARRAY['broadcast'::text, 'presence'::text])) AND (( SELECT realtime.topic() AS topic) ~~ 'inbox:%'::text) AND (((( SELECT realtime.topic() AS topic) ~~
    'inbox:org:%'::text) AND (substr(( SELECT realtime.topic() AS topic), 11) IN ( SELECT (x.x)::text AS x
   FROM better_supabase.tenant_ids_with('inbox.read'::text) x(x)))) OR
     ((( SELECT realtime.topic() AS topic) ~~ 'inbox:%'::text) AND (( SELECT realtime.topic() AS topic) !~~ 'inbox:org:%'::text) AND
     better_supabase.inbox_conversation_allowed(substr(( SELECT realtime.topic() AS topic), 7))))));

CREATE POLICY "bs_notifications_receive" ON "realtime"."messages"
  FOR SELECT
  TO "authenticated"
  USING
    (((EXTENSION = 'broadcast'::text) AND (( SELECT realtime.topic() AS topic) ~ ((('^'::text || 'notifications:'::text) || (( SELECT auth.uid() AS uid))::text) || '$'::text))));

CREATE POLICY "bs_realtime_tables_receive" ON "realtime"."messages"
  FOR SELECT
  TO "authenticated"
  USING
    (((EXTENSION = 'broadcast'::text) AND (( SELECT realtime.topic() AS topic) ~~ 'bs:t:%'::text) AND (NOT COALESCE(((( SELECT auth.jwt() AS jwt) ->>
    'is_anonymous'::text))::boolean,
    false)) AND
    ((split_part(( SELECT realtime.topic() AS topic), ':'::text, 4) = ''::text) OR ((split_part(( SELECT realtime.topic() AS topic), ':'::text, 5) = ''::text) AND (split_part((
    SELECT realtime.topic() AS topic),
    ':'::text,
    4) = COALESCE((( SELECT auth.jwt() AS jwt) ->> 'tenant_id'::text), ((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'tenant_id'::text), ''::text))) OR
    ((split_part(( SELECT realtime.topic() AS topic), ':'::text, 4) = 'u'::text) AND (split_part(( SELECT realtime.topic() AS topic), ':'::text, 5) = (( SELECT auth.uid() AS
    uid))::text)))));

