    ((name COLLATE "C") < (COALESCE((( SELECT auth.jwt() AS jwt) ->> 'tenant_id'::text), ((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'tenant_id'::text)) ||
    '0'::text)) AND
    (split_part(name, '/'::text, 1) = COALESCE((( SELECT auth.jwt() AS jwt) ->> 'tenant_id'::text), ((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'tenant_id'::text)))
    AND (name ~ '^[^/]+/[^/]+/logo/[^/]+\.webp$'::text)));

CREATE POLICY "bs_inbox_files_read" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'inbox-files'::text) AND better_supabase.inbox_file_allowed(name, false)));

CREATE POLICY "bs_inbox_files_write" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'inbox-files'::text) AND better_supabase.inbox_file_allowed(name, true) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

CREATE EVENT TRIGGER "bs_audit_forget_dropped"
  ON sql_drop
  WHEN TAG IN ('DROP SCHEMA', 'DROP TABLE')
  EXECUTE FUNCTION "better_supabase"."audit_forget_dropped"();

COMMENT ON COLUMN "public"."customers"."kvk" IS 'Chamber of Commerce (KvK) number.
@example "12345678"';

COMMENT ON COLUMN "public"."customers"."name" IS 'Trading name.
@example "Acme B.V."';

COMMENT ON CONSTRAINT "bs_audit_op_check" ON "better_supabase"."audit_events" IS 'better-supabase check 50fe4698';

COMMENT ON TABLE "public"."customers" IS 'Companies the organization sells to.';

